import struct, sys

def build(cls=2, data=1, ev=1, abi=0, abiver=0, pad=b'\0'*7,
          etype=2, machine=0x3e, version=1, entry=0x1000,
          phoff=None, shoff=None, flags=0, ehsize=None,
          phentsize=None, phnum=0, shentsize=None, shnum=0, shstrndx=0,
          phdrs=None, shdrs=None, extra=b'', tail=b'', truncate=None):
    """phdrs: list of dicts, shdrs: list of dicts"""
    end = '<' if data == 1 else '>'
    is64 = cls == 2
    ehsize_d = 64 if is64 else 52
    phentsize_d = 56 if is64 else 32
    shentsize_d = 64 if is64 else 40
    if ehsize is None: ehsize = ehsize_d
    if phentsize is None: phentsize = phentsize_d
    if shentsize is None: shentsize = shentsize_d
    phdrs = phdrs or []
    shdrs = shdrs or []
    if phnum == 0: phnum = len(phdrs)
    if shnum == 0: shnum = len(shdrs)

    ident = bytes([0x7f]) + b'ELF' + bytes([cls, data, ev, abi, abiver]) + pad
    body_off = ehsize_d
    if phoff is None: phoff = body_off if phdrs else 0
    phend = phoff + phentsize_d*len(phdrs)
    if shoff is None: shoff = phend if shdrs else 0

    def pack_ph(p):
        t = p.get('type',1); fl=p.get('flags',4); off=p.get('offset',0)
        va=p.get('vaddr',0); pa=p.get('paddr',va); fsz=p.get('filesz',0)
        msz=p.get('memsz',fsz); al=p.get('align',1)
        if is64:
            return struct.pack(end+'IIQQQQQQ', t, fl, off, va, pa, fsz, msz, al)
        return struct.pack(end+'IIIIIIII', t, off, va, pa, fsz, msz, fl, al)
    def pack_sh(s):
        nm=s.get('name',0); t=s.get('type',1); fl=s.get('flags',0); ad=s.get('addr',0)
        off=s.get('offset',0); sz=s.get('size',0); lk=s.get('link',0); inf=s.get('info',0)
        al=s.get('addralign',0); es=s.get('entsize',0)
        if is64:
            return struct.pack(end+'IIQQQQIIQQ', nm,t,fl,ad,off,sz,lk,inf,al,es)
        return struct.pack(end+'IIIIIIIIII', nm,t,fl,ad,off,sz,lk,inf,al,es)

    if is64:
        eh = ident + struct.pack(end+'HHIQQQIHHHHHH', etype, machine, version,
                entry, phoff, shoff, flags, ehsize, phentsize, phnum,
                shentsize, shnum, shstrndx)
    else:
        eh = ident + struct.pack(end+'HHIIIIIHHHHHH', etype, machine, version,
                entry, phoff, shoff, flags, ehsize, phentsize, phnum,
                shentsize, shnum, shstrndx)
    buf = bytearray(eh)
    def put(off, b):
        if off + len(b) > len(buf):
            buf.extend(b'\0' * (off + len(b) - len(buf)))
        buf[off:off+len(b)] = b
    for i,p in enumerate(phdrs):
        put(phoff + i*phentsize_d, pack_ph(p))
    for i,s in enumerate(shdrs):
        put(shoff + i*shentsize_d, pack_sh(s))
    for off, b in extra if extra else []:
        put(off, b)
    if tail:
        buf.extend(tail)
    if truncate is not None:
        del buf[truncate:]
    return bytes(buf)
EOF
