680	      }
681	
682	      function connect(sel1, sel2) {
683	          let elem1 = document.querySelector(sel1);
684	          let elem2 = document.querySelector(sel2);
685	
686	          if (elem1 === null || elem2 === null) {
687	              return;
688	          }
689	
690	          connections.push([elem1, elem2]);
691	
692	          addSvgArrow(elem1, elem2);
693	
694	          setJumpCallback(elem1, elem2);
695	          setJumpCallback(elem2, elem1);
696	      }
697	
698	      function clearArrows() {
699	          batchElems = '';
700	
701	          arrows.innerHTML = '';
702	      }
703	
704	      function pushArrowElems() {
705	          arrows.innerHTML = batchElems;
706	      }
707	
708	      function redrawArrows() {
709	          clearArrows();
710	
711	          for (let i = 0; i < connections.length; ++i) {
712	              let conn = connections[i];
713	
714	              addSvgArrow(conn[0], conn[1]);
715	          }
716	
717	          pushArrowElems();
718	      }
719	
720	      window.onresize = function() {
721	          redrawArrows();
722	      }
723	
724	      connect('.e_phoff', '.bin_phdr0');
725	      connect('.e_shoff', '.bin_shdr0');
726	      pushArrowElems();
727	    </script>
